  const rows=[['Price',x=>c.money(x.price)],['Quote type',x=>x.type],['Deposit',x=>c.money(x.price*.2)],['Included',x=>x.inc],['Excluded',x=>x.exc],['Extra charges',x=>x.extra],['Cancellation',x=>x.cancel],['Valid until',x=>x.valid],['Rating',()=>'No verified reviews yet'],['Status',x=>x.status]];
