const ENDPOINTS=[['GET','/v1/projects','Moving projects','{"data":[{"id":"prj_123","status":"quoting","from":{"zip":"78701"},"to":{"zip":"80202"}}],"has_more":false}'],['POST','/v1/quote-requests','Create quote request','{"id":"qr_456","status":"submitted","created":"2026-11-27T10:00:00Z"}'],['GET','/v1/quotes/{id}','Retrieve quote','{"id":"q_789","type":"binding","amount":485000,"currency":"usd","valid_until":"2026-12-07"}'],['GET','/v1/bookings/{id}','Retrieve booking','{"id":"bk_321","status":"confirmed","provider_id":"co_55"}'],['GET','/v1/tracking/{booking_id}','Tracking events','{"events":[{"type":"crew.en_route","at":"2026-11-27T08:01:00Z","source":"telematics","stale":false}]}'],['POST','/v1/webhook-endpoints','Register webhook','{"id":"we_11","url":"https://example.com/hooks","events":["booking.confirmed"]}']];
const EVENTS=['booking.created','booking.confirmed','booking.cancelled','quote.received','quote.accepted','payment.succeeded','refund.completed','job.dispatched','job.completed','claim.created','partner.verified','enterprise.relocation.approved'];
